  "package": "@astryxdesign/cli",
  "data": {
    "title": "Building a Theme Family",
    "content": [
      {
        "type": "prose",
        "text": "Use family mode when an app switches among one base theme and its selected descendants. The build writes one keyed CSS file containing every member, plus one keyed JavaScript module and one declaration file, beside the root source."
      },
      {
        "type": "code",
        "lang": "bash",
        "code": "astryx theme build --family \\\n  ./src/themes/ocean.mjs \\\n  ./src/themes/ocean-calm.mjs \\\n  ./src/themes/ocean-calm-deep.mjs \\\n  --family-key ocean-family",
        "label": "Build one family"
      },
      {
        "type": "prose",
        "text": "The family stylesheet eagerly downloads every selected member so first paint is complete. Switching members changes only the theme identity; it does not add, remove, or reorder stylesheets."
      }
    ],
    "id": "building-a-theme-family",
    "links": {
